from __future__ import annotations

from pathlib import Path

import click


CONTEXT_SETTINGS = {
    "help_option_names": ["-h", "--help"],
    "show_default": True,
}


def _path(value: str) -> str:
    """Return an absolute path without requiring the output to exist."""

    return str(Path(value).expanduser().resolve())


def _mapping_output_paths(output_prefix: str) -> dict[str, str]:
    """Return the standard files generated by the mapping command."""

    prefix = _path(output_prefix)
    return {
        "unique_bam": f"{prefix}.unique.bam",
        "multiplemap_bam": f"{prefix}.multiplemap.bam",
        "mapping_parquet": f"{prefix}.multiplemap.parquet",
        "log_file": f"{prefix}.mapping_mt.log",
    }


def _reference_output_paths(output_prefix: str) -> dict[str, str]:
    """Return the standard files generated by the reference command."""

    prefix = _path(output_prefix)
    return {
        "fasta": f"{prefix}.fa",
        "coordinate_tsv": f"{prefix}.coordinates.tsv",
        "transcript_paths_tsv": f"{prefix}.transcript_paths.tsv",
        "mappability_parquet": f"{prefix}.mappability.parquet",
    }


def _run_mapping(
    *,
    fastq: str,
    genome_fasta: str,
    transcript_fasta: str,
    coordinate_tsv: str,
    output_prefix: str,
    maximum_reads: int | None,
    transcript_candidate_count: int,
    kmer_size: int,
    window_size: int,
    minimum_minimizers: int,
    minimum_chain_score: int,
    minimum_dp_score: int,
    minimum_query_coverage: float,
    minimum_identity: float,
    worker_count: int,
    reads_per_worker: int,
    sort_threads: int,
    progress_interval: int,
    parquet_batch_size: int,
    multiprocessing_start_method: str,
) -> dict[str, str]:
    """Run mapping and return the generated file paths."""

    from mapping.map_read_mt import run_dual_mapping_to_bam_mt

    output_paths = _mapping_output_paths(output_prefix)
    Path(output_paths["unique_bam"]).parent.mkdir(parents=True, exist_ok=True)

    run_dual_mapping_to_bam_mt(
        fastq_path=_path(fastq),
        genome_fasta=_path(genome_fasta),
        transcript_fasta=_path(transcript_fasta),
        coordinate_tsv=_path(coordinate_tsv),
        unique_bam=output_paths["unique_bam"],
        multiplemap_bam=output_paths["multiplemap_bam"],
        mapping_parquet=output_paths["mapping_parquet"],
        maximum_reads=maximum_reads,
        transcript_candidate_count=transcript_candidate_count,
        kmer_size=kmer_size,
        window_size=window_size,
        minimum_minimizers=minimum_minimizers,
        minimum_chain_score=minimum_chain_score,
        minimum_dp_score=minimum_dp_score,
        minimum_query_coverage=minimum_query_coverage,
        minimum_identity=minimum_identity,
        worker_count=worker_count,
        reads_per_worker=reads_per_worker,
        sort_threads=sort_threads,
        progress_interval=progress_interval,
        parquet_batch_size=parquet_batch_size,
        log_file=output_paths["log_file"],
        multiprocessing_start_method=multiprocessing_start_method,
    )

    return output_paths


def _run_redistribution(
    *,
    coordinate_tsv: str,
    unique_bam: str,
    multiplemap_bam: str,
    mapping_parquet: str,
    mappability_parquet: str,
    output_prefix: str,
    pseudocount: float,
    maximum_iterations: int,
    convergence_threshold: float,
    maximum_allocation_error: float,
    random_seed: int,
    sort_threads: int,
    bam_progress_interval: int,
    parquet_batch_size: int,
):
    """Run EM redistribution and return its result object."""

    from re_distribute.run_redistribute import run_redistribution

    Path(_path(output_prefix)).parent.mkdir(parents=True, exist_ok=True)

    return run_redistribution(
        coordinate_tsv=_path(coordinate_tsv),
        unique_bam=_path(unique_bam),
        multiplemap_bam=_path(multiplemap_bam),
        mapping_parquet=_path(mapping_parquet),
        mappability_parquet=_path(mappability_parquet),
        output_prefix=_path(output_prefix),
        pseudocount=pseudocount,
        maximum_iterations=maximum_iterations,
        convergence_threshold=convergence_threshold,
        maximum_allocation_error=maximum_allocation_error,
        random_seed=random_seed,
        sort_threads=sort_threads,
        bam_progress_interval=bam_progress_interval,
        parquet_batch_size=parquet_batch_size,
    )


@click.group(context_settings=CONTEXT_SETTINGS)
@click.version_option(version="0.1.0", prog_name="RiboTxAlign")
def cli() -> None:
    """Build transcript references and map or redistribute Ribo-seq reads."""


@cli.command("create-reference")
@click.option(
    "--gencode-gff3",
    required=True,
    type=click.Path(exists=True, dir_okay=False, path_type=str),
    help="GENCODE annotation in GFF3 format.",
)
@click.option(
    "--stringtie-gtf",
    type=click.Path(exists=True, dir_okay=False, path_type=str),
    default=None,
    help="Optional StringTie transcript assembly in GTF format.",
)
@click.option(
    "--genome-fasta",
    required=True,
    type=click.Path(exists=True, dir_okay=False, path_type=str),
    help="Genome FASTA used to construct transcript sequences.",
)
@click.option(
    "--output-prefix",
    required=True,
    type=click.Path(path_type=str),
    help="Output prefix for the reference FASTA and associated tables.",
)
@click.option(
    "--flank-length",
    type=click.IntRange(min=0),
    default=40,
    help="Number of genomic flanking bases added to each reference.",
)
@click.option(
    "--mappability-read-length",
    type=click.IntRange(min=1),
    default=30,
    help="Read length used for exact-match mappability calculation.",
)
@click.option(
    "--mappability-step",
    type=click.IntRange(min=1),
    default=1,
    help="Sliding-window step used for mappability calculation.",
)
@click.option(
    "--mappability-progress-interval",
    type=click.IntRange(min=1),
    default=100,
    help="Number of references between mappability progress messages.",
)
def create_reference_command(
    gencode_gff3: str,
    stringtie_gtf: str | None,
    genome_fasta: str,
    output_prefix: str,
    flank_length: int,
    mappability_read_length: int,
    mappability_step: int,
    mappability_progress_interval: int,
) -> None:
    """Create a merged transcript reference and calculate mappability."""

    from db_construct.build_reference import build_common_gene_references
    from db_construct.calculate_mappability import calculate_reference_mappability

    output_prefix = _path(output_prefix)
    Path(output_prefix).parent.mkdir(parents=True, exist_ok=True)

    click.echo("Building the transcript reference...")
    gene_groups, novel_transcripts = build_common_gene_references(
        gencode_gff3=_path(gencode_gff3),
        stringtie_gtf=_path(stringtie_gtf) if stringtie_gtf else None,
        genome_fasta=_path(genome_fasta),
        output_prefix=output_prefix,
        flank_length=flank_length,
    )

    click.echo(f"Gene groups: {len(gene_groups):,}")
    click.echo(
        "StringTie transcripts not linked to GENCODE: "
        f"{len(novel_transcripts):,}"
    )

    reference_paths = _reference_output_paths(output_prefix)

    click.echo("Calculating exact-match mappability...")
    summary_df, _ = calculate_reference_mappability(
        reference_fasta=reference_paths["fasta"],
        coordinate_tsv=reference_paths["coordinate_tsv"],
        output_prefix=output_prefix,
        read_length=mappability_read_length,
        step=mappability_step,
        progress_gene_interval=mappability_progress_interval,
        write_position_table=False,
    )

    click.echo(f"Mappability references: {len(summary_df):,}")
    click.echo("Reference construction completed.")
    for label, path in reference_paths.items():
        click.echo(f"  {label}: {path}")


