    click.option(
        "--coordinate-tsv",
        required=True,
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    ),
    click.option(
        "--unique-bam",
        required=True,
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    ),
    click.option(
        "--multiplemap-bam",
        required=True,
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    ),
    click.option(
        "--mapping-parquet",
        required=True,
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    ),
    click.option(
        "--mappability-parquet",
        required=True,
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    ),
    click.option(
        "--output-prefix",
        required=True,
        type=click.Path(path_type=str),
    ),
    click.option("--pseudocount", type=click.FloatRange(min=0.0), default=0.01),
    click.option("--maximum-iterations", type=click.IntRange(min=1), default=100),
